class Solution {
public:
    long long maxOutput(int n, std::vector<std::vector<int>>& edges, std::vector<int>& price) {
        std::vector<std::vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        long long ans = 0;
        std::function<std::pair<long long, long long>(int, int)> dfs = [&](int u, int p) -> std::pair<long long, long long> {
            long long max_with = price[u];
            long long max_without = 0;
            for (int v : adj[u]) {
                if (v == p) continue;
                auto [cw, cwo] = dfs(v, u);
                ans = std::max(ans, std::max(max_with + cwo, max_without + cw));
                max_with = std::max(max_with, price[u] + cw);
                max_without = std::max(max_without, price[u] + cwo);
            }
            return {max_with, max_without};
        };
        dfs(0, -1);
        return ans;
    }
};

class Solution {
    private long ans = 0;
    public long maxOutput(int n, int[][] edges, int[] price) {
        java.util.List<Integer>[] adj = new java.util.ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new java.util.ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        ans = 0;
        dfs(0, -1, adj, price);
        return ans;
    }
    private long[] dfs(int u, int p, java.util.List<Integer>[] adj, int[] price) {
        long maxWith = price[u];
        long maxWithout = 0;
        for (int v : adj[u]) {
            if (v == p) continue;
            long[] child = dfs(v, u, adj, price);
            long cw = child[0], cwo = child[1];
            ans = Math.max(ans, Math.max(maxWith + cwo, maxWithout + cw));
            maxWith = Math.max(maxWith, price[u] + cw);
            maxWithout = Math.max(maxWithout, price[u] + cwo);
        }
        return new long[]{maxWith, maxWithout};
    }
}

var maxOutput = function(n, edges, price) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    let ans = 0n;
    const bPrice = price.map(BigInt);
    const dfs = (u, p) => {
        let maxWith = bPrice[u];
        let maxWithout = 0n;
        for (const v of adj[u]) {
            if (v === p) continue;
            const [cw, cwo] = dfs(v, u);
            const c1 = maxWith + cwo;
            const c2 = maxWithout + cw;
            if (c1 > ans) ans = c1;
            if (c2 > ans) ans = c2;
            if (bPrice[u] + cw > maxWith) maxWith = bPrice[u] + cw;
            if (bPrice[u] + cwo > maxWithout) maxWithout = bPrice[u] + cwo;
        }
        return [maxWith, maxWithout];
    };
    dfs(0, -1);
    return Number(ans);
};
